function renderNav(){ const nav=$("#categoryNav"); nav.innerHTML=categories.slice(1).map(c=>`<button class="nav-category ${activeCategory===c.id?"active":""}" data-category="${c.id}" aria-pressed="${activeCategory===c.id}"><span class="nav-category-icon">${categorySvg(c.id)}</span><span>${c.name}</span></button>`).join(""); $("#sideCategories").innerHTML=categories.slice(1).map(c=>`<button class="side-cat ${activeCategory===c.id?"active":""}" data-category="${c.id}"><span class="side-cat-icon">${categorySvg(c.id)}</span><span>${c.name}</span><span>${c.count}</span></button>`).join(""); const active=nav.querySelector(".nav-category.active"); if(active) active.scrollIntoView({behavior:"smooth",block:"nearest",inline:"nearest"});}
function categoryName(id){return categories.find(c=>c.id===id)?.name||"كل الخدمات"}
function filteredServices(){
 let arr=services.filter(s=>(activeCategory==="all"||s.category===activeCategory));
 const q=$("#searchInput").value.trim().toLowerCase(),city=$("#cityFilter").value,type=$("#typeFilter").value,min=Number($("#ratingFilter").value);
 arr=arr.filter(s=>{const r=getRating(s);return (!q||[s.title,s.provider,s.desc,s.city,categoryName(s.category)].join(" ").toLowerCase().includes(q))&&(city==="الكل"||s.city===city)&&(type==="الكل"||s.type===type)&&r.rating>=min});
 return arr.sort((a,b)=>sortHigh?getRating(b).rating-getRating(a).rating:getRating(a).rating-getRating(b).rating);
}
