function render(){
 renderNav();
 const arr=filteredServices();
 $("#postsView").innerHTML=arr.slice(0,visibleLimit).map(cardTemplate).join("");
 $("#resultsCount").textContent=`${arr.length} خدمة متاحة في العرض التجريبي`;
 $("#sectionTitle").textContent=activeCategory==="all"?"خدمات مختارة لك":categoryName(activeCategory);
 $("#sectionSubtitle").textContent=activeCategory==="all"?"تصفح خدمات متنوعة من مقدمي خدمات مستقلين وشركات محلية.":`استكشف ${categoryName(activeCategory)} من أفراد وشركات في مدن مختلفة.`;
 $("#emptyState").classList.toggle("hidden",arr.length!==0);
 $("#postsView").classList.toggle("hidden",activeView!=="posts"||arr.length===0);
 $("#mapView").classList.toggle("hidden",activeView!=="map");
 $("#sortBtn").innerHTML=(sortHigh?"الأعلى تقييما":"الأقل تقييما")+" <span>⌄</span>";
 $("#clearSearch").style.display=$("#searchInput").value?"block":"none";
 $("#loadMoreBtn").classList.toggle("hidden",activeView!=="posts"||arr.length<=visibleLimit);
 document.querySelectorAll(".view-btn").forEach(b=>b.classList.toggle("active",b.dataset.view===activeView));
 if(activeView==="map"){setTimeout(()=>renderMap(arr),100)}
}
function toast(msg){const t=$("#toast");t.textContent=msg;t.classList.add("show");clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove("show"),2600)}
function openModal(html){$("#modalContent").innerHTML=html;$("#modalBackdrop").classList.remove("hidden");document.body.style.overflow="hidden"}
function closeModal(){$("#modalBackdrop").classList.add("hidden");document.body.style.overflow="";$("#modalContent").innerHTML=""}
function serviceById(id){return services.find(s=>s.id===Number(id))}
function profileModal(id){
 const s=serviceById(id); if(!s)return;
 const own=services.filter(x=>x.provider===s.provider);
 const rating=own.length?own.reduce((sum,x)=>sum+getRating(x).rating,0)/own.length:getRating(s).rating;
 const reviews=own.reduce((sum,x)=>sum+getRating(x).reviews,0);
 const accountStars=`${"★".repeat(Math.max(0,Math.min(5,Math.round(rating)) ))}${"☆".repeat(5-Math.max(0,Math.min(5,Math.round(rating))))}`;
 const since=Number(s.id)<100?"عضو منذ 2025":"عضو جديد";
 const posts=own.map(x=>`<article class="social-post"><div class="social-post-head"><div class="profile-avatar-small">${escapeHtml(x.icon||x.provider.slice(0,1))}</div><div class="social-post-author"><b>${escapeHtml(x.provider)}</b><small>${escapeHtml(x.city)} · منشور خدمة تجريبي</small></div><span class="social-post-menu">•••</span></div><p class="social-post-copy">${escapeHtml(x.desc)}</p><img class="social-post-image" src="${x.image}" alt="${escapeHtml(x.title)}"><div class="social-post-meta"><span>★ ${getRating(x).rating.toFixed(1)} · ${getRating(x).reviews} تقييماً</span><span>${escapeHtml(x.price)}</span></div><div class="social-post-actions"><button type="button" data-detail="${x.id}">عرض تفاصيل الخدمة</button><button type="button" data-contact="${x.id}">✉ مراسلة</button></div></article>`).join("");
 openModal(`<div class="social-profile-cover"><span class="social-cover-label">Khedma Go · الملف الشخصي</span></div><div class="social-profile-top"><div class="profile-avatar-large">${escapeHtml(s.icon||s.provider.slice(0,1))}</div><div class="profile-heading"><h2 id="modalTitle">${escapeHtml(s.provider)} ${s.verified?'<span class="verified">✓</span>':''}</h2><p>${escapeHtml(s.type)} · ${escapeHtml(s.city)}</p><small>@${escapeHtml(String(s.social||s.provider).replace(/^@/,''))} · ${since}</small></div><button class="btn btn-primary social-message-top" data-contact="${s.id}">✉ مراسلة</button></div><p class="profile-bio">أهلاً بك في حساب ${escapeHtml(s.provider)}. هنا يمكنك التعرف على مقدم الخدمة، استعراض إعلاناته وأعماله وتقييماته، ومراسلته مباشرة عبر واجهة Khedma Go. <span>هذا حساب افتراضي لأغراض النموذج الأولي.</span></p><div class="social-profile-stats"><div><b>${own.length}</b><small>خدمات يقدمها الحساب</small></div><div><b>${accountStars}</b><small>متوسط تقييم الخدمات</small></div><div><b>${rating.toFixed(1)} / 5</b><small>التقييم العام للحساب</small></div></div><div class="social-profile-tabs"><span class="active">المنشورات</span><span>الخدمات</span><span>حول الحساب</span></div><section class="profile-section social-posts-section"><h3>المنشورات والأعمال</h3>${posts||'<p class="profile-empty">لم ينشر هذا الحساب خدمات بعد.</p>'}</section><section class="profile-section social-about"><h3>حول الحساب</h3><p>⌖ ${escapeHtml(s.city)}</p><p>▣ ${escapeHtml(s.type)} · مقدم خدمة على المنصة</p><p>★ ${rating.toFixed(1)} من 5، وهو متوسط تقييمات الخدمات المنشورة من هذا الحساب</p><p>◷ ${since}</p><p class="social-demo-note">التقييمات والمنشورات والأرقام المعروضة تجريبية وليست بيانات مستخدمين حقيقيين.</p></section><div class="modal-actions"><button class="btn btn-primary" data-contact="${s.id}">✉ مراسلة ${escapeHtml(s.provider)}</button><button class="btn btn-outline" data-detail="${s.id}">عرض تفاصيل الخدمة الحالية</button></div>`);
}
function detailModal(id){
 const s=serviceById(id);if(!s)return;const r=getRating(s);
 openModal(`<h2 id="modalTitle">${escapeHtml(s.title)}</h2><p class="modal-subtitle">${escapeHtml(s.provider)} · ${escapeHtml(s.type)} · ${escapeHtml(s.city)}</p><div class="service-provider-profile-link"><span class="provider-avatar">${escapeHtml(s.icon||s.provider.slice(0,1))}</span><div><b>${escapeHtml(s.provider)}</b><small>عارض الخدمة · ${escapeHtml(s.city)}</small></div><button type="button" class="btn btn-outline" data-profile="${s.id}">زيارة الحساب الشخصي ←</button></div><img class="detail-hero" src="${s.image}" alt="${escapeHtml(s.title)}"><div class="detail-grid"><div class="detail-chip"><small>التقييم</small><b style="color:#d99a36">★ ${r.rating.toFixed(1)} / 5 (${r.reviews} تقييم)</b></div><div class="detail-chip"><small>السعر</small><b>${escapeHtml(s.price)} ${escapeHtml(s.priceNote)}</b></div><div class="detail-chip"><small>المدينة</small><b>⌖ ${escapeHtml(s.city)}</b></div><div class="detail-chip"><small>نوع مقدم الخدمة</small><b>${escapeHtml(s.type)}</b></div></div><p class="detail-description">${escapeHtml(s.desc)}<br><br>هذا إعلان افتراضي لأغراض تجربة المنصة. تحقق من التفاصيل والمؤهلات قبل الاتفاق على أي خدمة.</p><div class="modal-actions"><button class="btn btn-primary" data-contact="${s.id}">✉ تواصل داخل الموقع</button><button class="btn btn-outline" data-demo-contact="${s.id}">☎ بيانات التواصل التجريبية</button><button class="btn btn-outline" data-rate="${s.id}">★ قيّم الخدمة</button></div>`);
}
function contactModal(id){
 const s=serviceById(id);if(!s)return;
 openModal(`<h2 id="modalTitle">مراسلة ${escapeHtml(s.provider)}</h2><p class="modal-subtitle">محادثة تجريبية · لا يتم إرسال الرسائل إلى شخص حقيقي.</p><div class="chat-window" id="chatWindow"><div class="chat-bubble">أهلا بك! هذه واجهة مراسلة تجريبية. كيف يمكنني مساعدتك بخصوص خدمة «${escapeHtml(s.title)}»؟<span class="chat-time">الآن</span></div></div><form class="chat-compose" id="chatForm"><input id="chatInput" placeholder="اكتب رسالتك هنا..." autocomplete="off" required><button class="btn btn-primary" type="submit">إرسال ←</button></form><div class="modal-actions"><button class="btn btn-outline" data-demo-contact="${s.id}">عرض بيانات التواصل التجريبية</button></div>`);
}
function externalContactModal(id){
 const s=serviceById(id);if(!s)return;
 openModal(`<h2 id="modalTitle">بيانات التواصل</h2><p class="modal-subtitle">هذه البيانات مولدة لأغراض العرض فقط وليست أرقاما حقيقية.</p><div class="detail-grid"><div class="detail-chip"><small>الهاتف التجريبي</small><b>${escapeHtml(s.phone)}</b></div><div class="detail-chip"><small>واتساب التجريبي</small><b>${escapeHtml(s.whatsapp)}</b></div><div class="detail-chip"><small>حساب اجتماعي تجريبي</small><b>${escapeHtml(s.social)}</b></div><div class="detail-chip"><small>المدينة</small><b>${escapeHtml(s.city)}</b></div></div><div class="modal-actions"><button class="btn btn-primary" id="copyContact">نسخ رقم تجريبي</button><button class="btn btn-outline" id="closeContact">إغلاق</button></div>`);
 $("#copyContact").onclick=()=>{if(navigator.clipboard&&navigator.clipboard.writeText)navigator.clipboard.writeText(s.phone).then(()=>toast("تم نسخ الرقم التجريبي")).catch(()=>toast("الرقم التجريبي: "+s.phone));else toast("الرقم التجريبي: "+s.phone)};
 $("#closeContact").onclick=closeModal;
}
function rateModal(id){
 const s=serviceById(id);if(!s)return;currentRating=0;
 openModal(`<h2 id="modalTitle">قيّم الخدمة</h2><p class="modal-subtitle">تقييمك تجريبي ومحفوظ في هذا المتصفح فقط.</p><p style="font-size:13px;margin:15px 0 4px">${escapeHtml(s.title)}</p><div class="stars-input" id="starsInput" aria-label="اختيار التقييم">${[1,2,3,4,5].map(n=>`<button type="button" class="star-pick" data-star="${n}" aria-label="${n} نجوم">★</button>`).join("")}</div><label class="field-label" for="reviewText">تعليق اختياري</label><textarea class="modal-textarea" id="reviewText" placeholder="اكتب رأيك حول الخدمة..."></textarea><div class="modal-actions"><button class="btn btn-primary" id="submitRating">إرسال التقييم</button><button class="btn btn-outline" id="cancelRating">إلغاء</button></div>`);
 $("#cancelRating").onclick=closeModal;
 $("#starsInput").onclick=e=>{const b=e.target.closest("[data-star]");if(!b)return;currentRating=Number(b.dataset.star);document.querySelectorAll(".star-pick").forEach(el=>el.classList.toggle("selected",Number(el.dataset.star)<=currentRating))};
 $("#submitRating").onclick=()=>{if(!currentRating){toast("اختر عدد النجوم أولا");return}if(userRatings[s.id]){toast("لقد أضفت تقييما تجريبيا لهذه الخدمة بالفعل");return}userRatings[s.id]={value:currentRating,text:$("#reviewText").value.trim()};try{localStorage.setItem("khidma-ratings",JSON.stringify(userRatings))}catch(e){}closeModal();render();toast("تم تسجيل تقييمك التجريبي")};
}
function addListingModal(){
 openModal(`<h2 id="modalTitle">أضف خدمتك</h2><p class="modal-subtitle">نموذج تجريبي لإنشاء إعلان. لن يُنشر على الإنترنت، وستضاف الخدمة إلى الصفحة الحالية فقط.</p><form id="listingForm"><div class="form-grid"><div><label class="field-label">اسم مقدم الخدمة</label><input class="modal-input" name="provider" required placeholder="مثال: أحمد للصيانة"></div><div><label class="field-label">نوع مقدم الخدمة</label><select class="modal-select" name="type"><option>فرد</option><option>حرفي</option><option>شركة</option></select></div><div class="wide"><label class="field-label">عنوان الخدمة</label><input class="modal-input" name="title" required placeholder="ما الخدمة التي تقدمها؟"></div><div><label class="field-label">الفئة</label><select class="modal-select" name="category">${categories.slice(1).map(c=>`<option value="${c.id}">${c.name}</option>`).join("")}</select></div><div><label class="field-label">المدينة</label><select class="modal-select" name="city">${Object.keys(cityCoords).map(c=>`<option>${c}</option>`).join("")}</select></div><div><label class="field-label">السعر</label><input class="modal-input" name="price" placeholder="مثال: 2000 دج"></div><div><label class="field-label">رقم تجريبي</label><input class="modal-input" name="phone" placeholder="0550 000 000"></div><div class="wide"><label class="field-label">وصف الخدمة</label><textarea class="modal-textarea" name="desc" required placeholder="اشرح الخدمة التي تقدمها..."></textarea></div></div><div class="modal-actions"><button class="btn btn-primary" type="submit">معاينة الإعلان</button><button class="btn btn-outline" type="button" id="cancelListing">إلغاء</button></div></form>`);
 $("#cancelListing").onclick=closeModal;
 $("#listingForm").onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),cat=f.get("category"),city=f.get("city"),coords=cityCoords[city];const s={id:Date.now(),category:cat,type:f.get("type"),provider:f.get("provider"),title:f.get("title"),desc:f.get("desc"),city,rating:5,reviews:0,price:f.get("price")||"حسب الاتفاق",priceNote:"سعر تجريبي",icon:String(f.get("provider")).slice(0,1),image:generatedServiceImage({id:Date.now(),title:f.get("title"),category:cat,icon:String(f.get("provider")).slice(0,1)}),lat:(city==="عنابة"?36.850+Math.random()*0.048:coords[0]+(Math.random()-.5)*.008),lng:(city==="عنابة"?7.690+Math.random()*0.045:coords[1]+(Math.random()-.5)*.008),phone:f.get("phone")||"0550 000 000",whatsapp:f.get("phone")||"0550 000 000",social:"@demo",verified:false};services.unshift(s);activeCategory=cat;activeView="posts";visibleLimit=30;closeModal();render();toast("تمت إضافة الإعلان إلى المعاينة التجريبية")};
}
function renderMap(arr){
 if(!window.L){$("#map").innerHTML='<div style="padding:35px;text-align:center;color:#66746c">تعذر تحميل مكتبة الخريطة. يمكنك متابعة تجربة عرض المنشورات.</div>';return}
 const city=$("#cityFilter").value!=="الكل"?$("#cityFilter").value:($("#sideCity").value||"عنابة");
 const center=cityCoords[city]||cityCoords["عنابة"];
 if(!mapInstance){
  mapInstance=L.map("map",{scrollWheelZoom:false,preferCanvas:true}).setView(center,12);
  // ESRI World Topographic Map avoids the blocked OSM tile endpoint and needs no CARTO key.
  // ArcGIS REST tile coordinates are ordered {z}/{y}/{x}.
  const base=L.tileLayer("https://server.arcgisonline.com/ArcGIS/rest/services/World_Topo_Map/MapServer/tile/{z}/{y}/{x}",{
   attribution:'Tiles &copy; <a href="https://www.esri.com/" target="_blank" rel="noopener">Esri</a>',
   maxZoom:19, minZoom:2, tileSize:256, updateWhenIdle:true, keepBuffer:3, crossOrigin:true
  });
  base.addTo(mapInstance);
 }else{mapInstance.setView(center,12)}
 mapMarkers.forEach(m=>mapInstance.removeLayer(m));mapMarkers=[];
 arr.forEach(s=>{const marker=L.marker([s.lat,s.lng]).addTo(mapInstance);const rating=getRating(s);marker.bindPopup(`<div class="map-popup"><img class="map-popup-image" src="${escapeHtml(s.image)}" alt="${escapeHtml(s.title)}" onerror="this.style.display='none'"><div class="map-popup-content"><span class="map-popup-category">${escapeHtml(categoryName(s.category))}</span><b class="map-popup-title">${escapeHtml(s.title)}</b><div class="map-popup-provider">${escapeHtml(s.icon||s.provider.slice(0,1))} <strong>${escapeHtml(s.provider)}</strong> ${s.verified?'<span class="map-popup-verified">✓ موثّق</span>':''}</div><div class="map-popup-meta"><span class="map-popup-rating">★ ${rating.rating.toFixed(1)} <small>(${rating.reviews} تقييم)</small></span><span>⌖ ${escapeHtml(s.city)}</span></div><div class="map-popup-price">${escapeHtml(s.price)} <small>${escapeHtml(s.priceNote||'')}</small></div><button onclick="window.openServiceDetails(${s.id})">عرض تفاصيل الخدمة ←</button></div></div>`,{maxWidth:270,minWidth:230});mapMarkers.push(marker)});
 if(arr.length){const matching=arr.filter(s=>s.city===city);const fit=(matching.length?matching:arr).map(s=>[s.lat,s.lng]);if(fit.length>1)mapInstance.fitBounds(fit,{padding:[30,30],maxZoom:13});else mapInstance.setView(fit[0],13)}
 setTimeout(()=>mapInstance.invalidateSize(),100);
}
window.openServiceDetails=id=>detailModal(id);
const categoryStrip=$("#categoryNav");
categoryStrip.addEventListener("wheel",e=>{
 if(Math.abs(e.deltaY)>Math.abs(e.deltaX) && categoryStrip.scrollWidth>categoryStrip.clientWidth){
  e.preventDefault(); categoryStrip.scrollBy({left:e.deltaY,behavior:"auto"});
 }
},{passive:false});
categoryStrip.addEventListener("keydown",e=>{
 if(e.key==="ArrowRight"||e.key==="ArrowLeft"){
  const buttons=[...categoryStrip.querySelectorAll(".nav-category")],index=buttons.indexOf(document.activeElement);
  if(index>=0){e.preventDefault();buttons[Math.max(0,Math.min(buttons.length-1,index+(e.key==="ArrowRight"?1:-1)))].focus();buttons[Math.max(0,Math.min(buttons.length-1,index+(e.key==="ArrowRight"?1:-1)))].scrollIntoView({behavior:"smooth",block:"nearest",inline:"nearest"});}
 }
});
document.addEventListener("click",e=>{
 const cat=e.target.closest("[data-category]");if(cat){activeCategory=cat.dataset.category;visibleLimit=9;render();return}
 const view=e.target.closest("[data-view]");if(view){activeView=view.dataset.view;render();return}
 const profile=e.target.closest("[data-profile]");if(profile){profileModal(profile.dataset.profile);return}
 const detail=e.target.closest("[data-detail]");if(detail){detailModal(detail.dataset.detail);return}
 const contact=e.target.closest("[data-contact]");if(contact){contactModal(contact.dataset.contact);return}
 const ext=e.target.closest("[data-demo-contact]");if(ext){externalContactModal(ext.dataset.demoContact);return}
 const rate=e.target.closest("[data-rate]");if(rate){rateModal(rate.dataset.rate);return}
 const save=e.target.closest("[data-save]");if(save){save.classList.toggle("saved");save.textContent=save.classList.contains("saved")?"♥":"♡";toast(save.classList.contains("saved")?"تم حفظ الخدمة في هذه المعاينة":"تمت إزالة الخدمة من المحفوظات");return}
});
document.addEventListener("submit",e=>{if(e.target.id==="chatForm"){e.preventDefault();const input=$("#chatInput"),val=input.value.trim();if(!val)return;const bubble=document.createElement("div");bubble.className="chat-bubble mine";bubble.textContent=val;const time=document.createElement("span");time.className="chat-time";time.textContent="الآن · رسالة تجريبية";bubble.appendChild(time);$("#chatWindow").appendChild(bubble);input.value="";$("#chatWindow").scrollTop=$("#chatWindow").scrollHeight;setTimeout(()=>{if($("#chatWindow")){const reply=document.createElement("div");reply.className="chat-bubble";reply.textContent="شكرا على رسالتك! هذه إجابة آلية ضمن النموذج الأولي.";const tm=document.createElement("span");tm.className="chat-time";tm.textContent="الآن";reply.appendChild(tm);$("#chatWindow").appendChild(reply);$("#chatWindow").scrollTop=$("#chatWindow").scrollHeight}},450)}});
["searchInput","cityFilter","typeFilter","ratingFilter"].forEach(id=>$("#"+id).addEventListener(id==="searchInput"?"input":"change",()=>{visibleLimit=9;render()}));
$("#clearSearch").onclick=()=>{$("#searchInput").value="";render();$("#searchInput").focus()};
$("#resetFilters").onclick=()=>{$("#searchInput").value="";$("#cityFilter").value="الكل";$("#typeFilter").value="الكل";$("#ratingFilter").value="0";render()};
$("#sortBtn").onclick=()=>{sortHigh=!sortHigh;render()};
$("#loadMoreBtn").onclick=()=>{visibleLimit+=6;render()};
$("#addListingBtn").onclick=addListingModal;
$("#profileBtn").onclick=()=>toast("الحساب الشخصي غير مفعل في النموذج الأولي");
$("#aboutLink").onclick=e=>{e.preventDefault();openModal(`<h2 id="modalTitle">عن Khedma Go</h2><p class="modal-subtitle">Khedma Go هي فكرة منصة تربط العملاء بمقدمي الخدمات المستقلين والشركات المحلية. هذا النموذج تجريبي، وجميع الإعلانات والأرقام والتقييمات ومواقع مقدمي الخدمات بيانات افتراضية وليست توصيات أو جهات حقيقية.</p><div class="detail-chip"><small>هدف النموذج</small><b>تجربة تصفح الخدمات، والبحث، والخريطة، والتقييمات، والتواصل التجريبي.</b></div>`)}
document.querySelectorAll("[data-footer-modal]").forEach(link=>link.addEventListener("click",e=>{
 e.preventDefault();
 const pages={
  privacy:["سياسة الخصوصية","هذه نسخة تجريبية لا تهدف إلى جمع بيانات شخصية حقيقية أو معالجة مدفوعات. قد تتفاعل مع حقول البحث والنماذج داخل المتصفح لأغراض العرض فقط. لا تُدخل كلمات مرور أو معلومات مالية أو بيانات شخصية حساسة في هذه المعاينة. ستحتاج سياسة الخصوصية النهائية إلى مراجعة وتحديث قبل إطلاق المنصة فعليًا."],
  terms:["شروط الاستخدام","يُتاح هذا النموذج للتجربة والتقييم فقط. البيانات والإعلانات والتقييمات والمواقع المعروضة تجريبية وقد لا تعكس خدمات أو أشخاصًا حقيقيين. لا تُنشئ المعاينة اتفاقًا تجاريًا ولا تضمن توفر أي خدمة. يجب اعتماد شروط نهائية ومراجعتها قانونيًا قبل الإطلاق الفعلي."],
  service:["سياسة الخدمات والإعلانات","مقدمو الإعلانات هم المسؤولون عن صحة بيانات الإعلان ووصف الخدمة والأسعار والتوفر وجودة التنفيذ وأي اتفاق مباشر مع العميل. المنصة ليست مقدم الخدمة ولا تنفذ الأعمال المعروضة. في هذه النسخة، الإعلانات والبيانات تجريبية ولا ينبغي الاعتماد عليها لطلب خدمة حقيقية."],
  contact:["تواصل معنا","قناة التواصل الرسمية لم تُفعّل بعد لأن Khedma Go ما زالت نموذجًا أوليًا قيد التطوير. أزرار التواصل داخل الموقع تجريبية ولا ترسل رسائل إلى جهة حقيقية. ستُضاف معلومات الاتصال الرسمية عند الانتقال إلى مرحلة الإطلاق."],
  safety:["مسؤولية مقدمي الخدمات","يتحمل ناشر الإعلان مسؤولية صحة المعلومات، والالتزام بالأنظمة المعمول بها، وسلامة الخدمة وجودتها، والاتفاق على السعر والموعد وشروط التنفيذ. لا تمثل الإعلانات أو التقييمات التجريبية توثيقًا أو ضمانًا من المنصة، ولا تؤكد المنصة في هذه المرحلة هوية مقدمي الخدمات."],
  demo:["حول النسخة التجريبية","أُنشئت Khedma Go كنموذج أولي لعرض فكرة منصة تربط طالبي الخدمات بمقدميها، وذلك ضمن مشروع قيد التطوير يُراد تقديمه في مسار الحصول على شهادة مؤسسة ناشئة. هذه العبارة تصف هدف المشروع ولا تعني أن شهادة قد مُنحت بالفعل أو أن المنصة معتمدة رسميًا."]
 };
 const [title,body]=pages[link.dataset.footerModal];
 openModal(`<h2 id="modalTitle">${title}</h2><p class="modal-subtitle">${body}</p><div class="detail-chip"><small>حالة المشروع</small><b>نموذج أولي تجريبي · المعلومات القانونية المعروضة أولية وتحتاج مراجعة قبل الإطلاق التجاري.</b></div>`);
}));
$("#showNearbyBtn").onclick=()=>{const city=$("#sideCity").value;$("#cityFilter").value=city;activeView="map";render();window.scrollTo({top:$("#sectionTitle").getBoundingClientRect().top+window.scrollY-105,behavior:"smooth"})};
$("#sideCity").onchange=()=>{if(activeView==="map")render()};
$("#modalClose").onclick=closeModal;
$("#modalBackdrop").addEventListener("click",e=>{if(e.target===$("#modalBackdrop"))closeModal()});
document.addEventListener("keydown",e=>{if(e.key==="Escape")closeModal()});
// v25: persistent side drawer, appearance toggle, and language preference preview
const drawer = document.getElementById("sideDrawer");
const drawerScrim = document.getElementById("drawerScrim");
function setDrawer(open){
  drawer.classList.toggle("is-open",open); drawerScrim.classList.toggle("is-visible",open);
  document.body.classList.toggle("drawer-open",open);
  drawer.setAttribute("aria-hidden",String(!open));
  $("#menuTrigger").setAttribute("aria-expanded",String(open));
}
$("#menuTrigger").addEventListener("click",()=>setDrawer(!drawer.classList.contains("is-open")));
$("#drawerClose").addEventListener("click",()=>setDrawer(false));
drawerScrim.addEventListener("click",()=>setDrawer(false));
$("#drawerCategories").innerHTML=categories.map(c=>`<button class="drawer-category ${c.id===activeCategory?'active':''}" data-category="${c.id}"><span class="drawer-category-icon">${c.icon}</span><span>${c.name}</span><small>${c.count}</small></button>`).join("");
$("#drawerCategories").addEventListener("click",e=>{if(e.target.closest("[data-category]"))setDrawer(false)});
$("#themeToggle").addEventListener("click",()=>{
 const dark=document.body.classList.toggle("dark-mode");
 $("#themeToggle").classList.toggle("is-dark",dark); $("#themeToggle").setAttribute("aria-pressed",String(dark));
 $("#themeToggle").querySelector("small").textContent=dark?"داكن":"فاتح";
});
$("#languageSelect").addEventListener("change",e=>toast(e.target.value==="en"?"English selected for preview. Full translation is not enabled yet.":"تم اختيار العربية. الترجمة الكاملة غير مفعّلة بعد."));
$("#drawerAbout").addEventListener("click",e=>{e.preventDefault();setDrawer(false);$("#aboutLink").click()});
document.querySelectorAll("#sideDrawer [data-footer-modal]").forEach(link=>link.addEventListener("click",()=>setDrawer(false)));
document.addEventListener("keydown",e=>{if(e.key==="Escape")setDrawer(false)});

render();
